<?php
require __DIR__.'/app/public.php';$pageTitle='Tournament & archive · Smoky Mountain Cup';
$seasons=safe_public_data(fn()=>rows('SELECT * FROM cup_seasons ORDER BY active DESC,id DESC'));
$seasonId=filter_var($_GET['season']??0,FILTER_VALIDATE_INT)?:($seasons[0]['id']??0);
$categories=safe_public_data(fn()=>rows('SELECT c.*,k.name AS category_name FROM cup_competitions c JOIN cup_categories k ON k.id=c.category_id WHERE c.season_id=? AND c.published=1 ORDER BY k.name',[$seasonId]));
$cid=filter_var($_GET['category']??0,FILTER_VALIDATE_INT)?:($categories[0]['id']??0);
$c=null;foreach($categories as $item)if((int)$item['id']===$cid)$c=$item;
$view=in_array($_GET['view']??'', ['fixtures','standings','bracket','scorers'],true)?$_GET['view']:'standings';
$matches=$c?safe_public_data(fn()=>match_list((int)$seasonId,(int)$cid)):[];
$base='tournament.php?season='.(int)$seasonId.'&category='.(int)$cid;
$provisional=!empty($_GET['provisional']) && $c && !$c['historical'];
require __DIR__.'/php/secction/header.php';
?><main id="main-content" class="cup-section"><p class="cup-eyebrow">SMOKY MOUNTAIN CUP</p><h1>Tournament center</h1><div class="cup-toolbar"><form method="get"><label>Season<select name="season" onchange="this.form.submit()"><?php foreach($seasons as $s):?><option value="<?=$s['id']?>" <?=$s['id']==$seasonId?'selected':''?>><?=h($s['name'])?><?=$s['archived']?' · Archive':''?></option><?php endforeach;?></select></label><noscript><button>Show season</button></noscript></form><a href="tournament.php?view=fixtures">Current matchday ↗</a></div>
<nav class="cup-tabs" aria-label="Categories"><?php foreach($categories as $cat):?><a class="<?=$cid==$cat['id']?'active':''?>" href="tournament.php?season=<?=$seasonId?>&category=<?=$cat['id']?>&view=<?=h($view)?>"><?=h($cat['category_name'])?></a><?php endforeach;?></nav>
<?php if(!$c):?><p class="cup-empty">The next competition will be published here. Check back for teams and fixtures.</p><?php else:?>
<nav class="cup-tabs" aria-label="Competition views"><?php foreach(['standings'=>'Groups & standings','fixtures'=>'Fixtures & results','bracket'=>'Knockout bracket','scorers'=>'Top scorers'] as $key=>$label):?><a class="<?=$view===$key?'active':''?>" href="<?=h($base.'&view='.$key)?>"><?=$label?></a><?php endforeach;?></nav>
<?php if($c['historical']):?><p class="cup-stale">Historical import. Original statistics are preserved and may contain inconsistencies. Match schedules and scorers may be incomplete.</p><?php endif;?>
<?php if($view==='fixtures'):?><div class="cup-match-grid"><?php foreach($matches as $m)match_card($m);?></div><?php if(!$matches):?><p class="cup-empty">Fixtures have not been published yet.</p><?php endif;?>
<?php elseif($view==='standings'):
    $stats=safe_public_data(fn()=>standings((int)$cid,$provisional));
    if(!$c['historical']):?><p><a href="<?=h($base.'&view=standings')?>">Official standings</a> · <a href="<?=h($base.'&view=standings&provisional=1')?>">Live provisional standings</a></p><p class="cup-muted"><?=$provisional?'Provisional: includes ongoing and unconfirmed matches.':'Official: confirmed results only.'?></p><div data-live-standings="<?=$cid?>" data-provisional="<?=$provisional?'1':'0'?>"></div><?php endif;
    if($c['historical']) {
        $legacy=safe_public_data(fn()=>rows("SELECT * FROM cup_legacy WHERE source_table='team_stats'"));$map=[];
        foreach(safe_public_data(fn()=>rows("SELECT * FROM cup_legacy WHERE source_table='teams'")) as $r)$map[$r['source_id']]=json_decode($r['note'],true)['target_id']??null;
        foreach($legacy as $r){$old=json_decode($r['payload'],true);foreach($stats as &$st)if($st['team_id']==($map[$old['team_id']]??0)){foreach(['played'=>'games_played','wins'=>'wins','draws'=>'draws','losses'=>'losses','gf'=>'goals_scored','ga'=>'goals_conceded','gd'=>'goal_difference','points'=>'points'] as $new=>$key)$st[$new]=(int)$old[$key];}unset($st);}
    }
    ?><div id="cup-standings-tables"><?php $group=false;foreach($stats as $st):if($group!==$st['group_id']):if($group!==false):?></tbody></table></div><?php endif;$group=$st['group_id'];?><h2><?=h($st['group_name']??'Teams')?></h2><div class="cup-table-wrap"><table><thead><tr><th>Team</th><th>P</th><th>W</th><th>D</th><th>L</th><th>GF</th><th>GA</th><th>GD</th><th>Pts</th></tr></thead><tbody><?php endif;?><tr><td><?=h($st['name'])?></td><?php foreach(['played','wins','draws','losses','gf','ga','gd','points'] as $key):?><td><?=$st[$key]?></td><?php endforeach;?></tr><?php endforeach;if($stats):?></tbody></table></div><?php endif;?></div><p class="cup-muted">Tie-breakers: points, goal difference, goals scored; remaining ties are resolved by the organizers.</p>
<?php elseif($view==='bracket'):$rounds=[];foreach($matches as $m)if($m['stage']==='knockout')$rounds[$m['round_no']][]=$m;ksort($rounds);?><div class="cup-bracket"><?php foreach($rounds as $n=>$games):?><section class="cup-bracket-round"><h2>Round <?=$n?></h2><?php foreach($games as $m)match_card($m);?></section><?php endforeach;?></div><?php if(!$rounds):?><p class="cup-empty">The knockout bracket has not been published.</p><?php endif;?>
<?php else:$scorers=safe_public_data(fn()=>rows("SELECT p.name,r.number,t.name AS team,COUNT(e.id) AS goals FROM cup_events e JOIN cup_matches m ON m.id=e.match_id JOIN cup_rosters r ON r.id=e.roster_id JOIN cup_players p ON p.id=r.player_id JOIN cup_entries en ON en.id=e.entry_id JOIN cup_teams t ON t.id=en.team_id WHERE m.competition_id=? AND m.confirmed=1 AND e.voided=0 AND e.kind='goal' GROUP BY p.id,p.name,r.number,t.name ORDER BY goals DESC,p.name",[$cid]));?><h2>Top scorers</h2><div class="cup-table-wrap"><table><tr><th>Player</th><th>Team</th><th>Goals</th></tr><?php foreach($scorers as $s):?><tr><td>#<?=$s['number']?> <?=h($s['name'])?></td><td><?=h($s['team'])?></td><td><?=$s['goals']?></td></tr><?php endforeach;?></table></div><?php if(!$scorers):?><p class="cup-muted">No confirmed goals with an identified scorer yet.</p><?php endif;?><?php endif;?>
<?php endif;?></main><?php require __DIR__.'/php/secction/footer.php';?>
